export type StateAtom = {key:string;subject:string;value:string|number|boolean|null;known:boolean;establishedAt:number|null;witnesses:Witness[]};
export type Witness = {sourceId:string;path:string;quote:string};
export type ScenarioEvent = {id:string;time:number;actor:string;meaning:string;witnesses:Witness[]};
export type SourceClause = {id:string;meaning:string;witnesses:Witness[]};
export type ProbeFrame = {event:ScenarioEvent;atoms:StateAtom[];selectedClauses:SourceClause[];guardValue:boolean|null};
